//! Compare predictions to identical measured complex lag products and working errors.
use anyhow::Result;use rustplotlib::*;use serde_json::Value;use std::path::Path;
fn main()->Result<()>{let a:Vec<_>=std::env::args().collect();let f=hdf5::File::open(&a[1])?;let d:Value=serde_json::from_slice(&f.dataset("json_utf8")?.read_raw::<u8>()?)?;let q=&d["quality"];let z=q["height_km"].as_array().unwrap();let out=Path::new(&a[2]);std::fs::create_dir_all(out)?;let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=195.;fig.height_mm=250.;fig.latex.cache=out.join("latex-cache");for(row,target)in [300.,450.,600.,850.].iter().enumerate(){let g=(0..z.len()).min_by(|a,b|(z[*a].as_f64().unwrap()-target).abs().total_cmp(&(z[*b].as_f64().unwrap()-target).abs())).unwrap();let scale=q["observed"][g*62][0].as_f64().unwrap().abs().max(1e-12);for part in 0..2{let mut data=vec![];let mut jp=vec![];let mut gp=vec![];let mut errors=vec![];let(mut low,mut high)=(0f64,0f64);for l in 0..62{let x=(l+1)as f64*10.;let y=q["observed"][g*62+l][part].as_f64().unwrap()/scale;let e=q["sigma"][g*62+l][part].as_f64().unwrap()/scale;let j=q["joint_prediction"][g*62+l][part].as_f64().unwrap()/scale;let p=q["gated_prediction"][g][l][part].as_f64().unwrap()/scale;low=low.min(y-e).min(j).min(p);high=high.max(y+e).max(j).max(p);data.push([x,y]);errors.push([y-e,y+e]);jp.push([x,j]);gp.push([x,p]);}let range=(high-low).max(0.1);low-=range*0.1;high+=range*0.1;let mut ax=Axes::new([0.,630.],[low,high],if row==3{r"Lag ($\mu$s)"}else{""},if part==0{r"Re ACF / Re R(10 $\mu$s)"}else{r"Im ACF / Re R(10 $\mu$s)"});ax.xticks=vec![0.,200.,400.,600.];if row<3{ax.show_x_axis=false;}let rect=Rect::new(24.+part as f64*91.,20.+row as f64*52.,67.,34.);let mut p=Panel::new(rect,ax);let joint=Line::series(jp,0);let gated=Line::series(gp,1);if row==0&&part==0{p.legend=Some(Legend::new(vec![joint.legend("Joint spline"),gated.legend("Gated")]));}p.push(Layer::Line(joint));p.push(Layer::Line(gated));p.errorbars(&data,None,Some(&errors),"black",0.5,1.,0.5)?;p.markers(&mut fig,&data,&MarkerStyle{shape:MarkerShape::Circle,size_pt:1.8,color:[0.,0.,0.]})?;fig.panels.push(p);fig.labels.push(Label::new(format!("{:.0} km",z[g].as_f64().unwrap()),rect.x+rect.width/2.,rect.y-5.));}}
fig.labels.push(Label::new("SYISR zenith: measured lag products and forward predictions",97.5,5.));fig.labels.push(Label::new("07:30--08:00 local; common measured normalization; bars show working standard errors",97.5,240.));fig.save(out.join("gated-vs-joint-acfs.png"))?;Ok(())}
